const komisi = $('Baca Komisi').all().map((i) => i.json)
  .filter((r) => r && r.order_id && String(r.status || '').toUpperCase() === 'UNPAID');
const resellers = $('Baca Resellers').all().map((i) => i.json).filter((r) => r && r.kode);

const byKode = {};
for (const k of komisi) {
  const kode = String(k.kode || '').toUpperCase();
  if (!kode) continue;
  (byKode[kode] = byKode[kode] || []).push(k);
}

const fmt = (n) => Number(n || 0).toLocaleString('id-ID');
const periode = `s/d ${new Date().toLocaleDateString('id-ID', { timeZone: 'Asia/Jakarta', day: 'numeric', month: 'long', year: 'numeric' })}`;

const kirim = [];
const anomali = [];
const barisOwner = [];
let totalSemua = 0;

for (const [kode, rows] of Object.entries(byKode)) {
  const r = resellers.find((x) => String(x.kode).toUpperCase() === kode);
  const total = rows.reduce((s, x) => s + (parseFloat(x.komisi) || 0), 0);
  totalSemua += total;

  barisOwner.push(`• ${kode}${r ? ` (${r.nama})` : ''} · ${rows.length} order · Rp ${fmt(total)}${r ? ` → ${r.bank} ${r.norek}` : ' → ⚠️ data reseller tidak ditemukan'}`);

  const wa = r ? String(r.wa || '').replace(/\D/g, '') : '';
  if (!wa) { anomali.push(kode); continue; }

  // Template 7a docs/copywriting-pesan.md (rincian tanpa kolom paket — tidak ada di tab komisi)
  const rincian = rows.map((x) => `• #${x.order_id} · order Rp ${fmt(x.total_order)} · komisi Rp ${fmt(x.komisi)}`).join('\n');
  kirim.push({ wa, teks: `💸 *Rekap Komisi hariH* — ${periode}\n\nHalo ${r.nama}! Ini hasil penjualanmu:\n\n${rincian}\n\nTotal komisi: *Rp ${fmt(total)}*\nPayout ke ${r.bank} ${r.norek} diproses hari ini.\n\nTerima kasih & semangat terus! 🚀\n— hariH` });
}

let ownerWa = String($env.OWNER_WA || '').replace(/\D/g, '');
if (ownerWa.startsWith('0')) ownerWa = '62' + ownerWa.slice(1);
else if (ownerWa.startsWith('8')) ownerWa = '62' + ownerWa;

// Template 7b — juga dikirim saat kosong (heartbeat mingguan: WF-04 hidup)
const jumlah = Object.keys(byKode).length;
const ownerTeks = jumlah === 0
  ? `📊 *[hariH] Rekap komisi — ${periode}*\n\nTidak ada komisi UNPAID minggu ini.`
  : `📊 *[hariH] Rekap komisi — ${periode}*\n\n${jumlah} reseller · total payout *Rp ${fmt(totalSemua)}*\n\n${barisOwner.join('\n')}${anomali.length ? `\n\n⚠️ Rekap tidak terkirim ke: ${anomali.join(', ')} (data/nomor bermasalah)` : ''}\n\n✅ Setelah transfer, ubah status di sheet komisi → PAID.`;

return [{ json: { owner_wa: ownerWa, owner_teks: ownerTeks, kirim } }];
